 "content": "def transform(grid):
    """Fill the trailing background cells of the first row in each colored band."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    in_band = False
    for r, row in enumerate(grid):
        active = any(v != bg for v in row)
        if active and not in_band:
            # This is the top row of a horizontal pattern band.
            occupied = [c for c, v in enumerate(row) if v != bg]
            if occupied:
                for c in range(max(occupied) + 1, w):
                    out[r][c] = 1
        in_band = active
    return out

if __name__ == '__main__':
    pass
