 "content": "def transform(grid):
    """Mark the rightward continuation of a truncated repeated row-pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    active = [r for r, row in enumerate(grid) if any(x != bg for x in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # Repeated motifs occur in two vertically separated copies. Compare their
    # corresponding rows; the copy with the shorter foreground extent is the
    # truncated one. Continue it with marker 1 wherever the other copy carries
    # foreground in that right-hand region.
    if len(bands) >= 2:
        for a in range(len(bands)):
            for b in range(a + 1, len(bands)):
                top, bottom = bands[a], bands[b]
                if len(top) != len(bottom):
                    continue
                for i in range(len(top)):
                    r1, r2 = top[i], bottom[i]
                    end1 = max((c for c,v in enumerate(grid[r1]) if v != bg), default=-1)
                    end2 = max((c for c,v in enumerate(grid[r2]) if v != bg), default=-1)
                    if end1 == end2:
                        continue
                    short, long = (r1, r2) if end1 < end2 else (r2, r1)
                    short_end = min(end1, end2)
                    for c in range(short_end + 1, w):
                        if grid[short][c] == bg and grid[long][c] != bg:
                            out[short][c] = 1
    return out

if __name__ == '__main__':
