    bg = max(counts, key=counts.get)

    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    if len(bands) >= 2:
        upper, lower = bands[0], bands[-1]
        if len(upper) == len(lower):
            for i, r in enumerate(lower):
                source = grid[upper[i]]
                target = grid[r]
                # Color the missing continuation slots of each repeating
                # three-column motif, starting after the displayed template.
                last = max((c for c, v in enumerate(target) if v != bg), default=-1)
                start = last + 1
                # The continuation is the pattern in the corresponding source
                # row repeated across the rest of the width.
                for c in range(start, w):
                    if source[c] != bg:
                        out[r][c] = 1
