            rows = [r for r in active_rows]
            if len(rows) >= 2:
                r = rows[0]
                last = max((c for c, v in enumerate(grid[r]) if v != bg), default=-1)
                if last >= 0:
                    for c in range(last + 1, w):
                        out[r][c] = 1
    return out

