 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # Complete the final (truncated) patterned band: extend each row's visible
    # colored segment to the right edge using marker color 1.
    if len(bands) >= 2:
        for r in bands[-1]:
            last = max((c for c, value in enumerate(grid[r]) if value != bg), default=-1)
            for c in range(last + 1, w):
                out[r][c] = 1
    return out

