{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u067/system/state/workspace/programs/task-1f77d9b6.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # The lower copy is the completed reference. Add its foreground cells to
    # the corresponding upper copy, using 1 to distinguish the completion.
    if len(bands) >= 2:
        upper, reference = bands[0], bands[-1]
        if len(upper) == len(reference):
            for upper_r, ref_r in zip(upper, reference):
                for c in range(w):
                    if grid[upper_r][c] == bg and grid[ref_r][c] != bg:
                        out[upper_r][c] = 1
    return out

